    {
      "contract_id": "01a1ff42-7bd0-7d9e-883a-1059368cd356",
      "created_at": "2026-11-21T17:59:44.513906+00:00",
      "evidence": {
        "delegation_ref": "01a1ff1f-e4ba-72dc-9c1a-13049933cf14",
